//! 🧹️ A cascade removes original selected rows through separately funded immutable splices.
use super::*;
use crate::row::{RowListPreparation,RowChange};
use semio_framework_value_persistent::list::persistent::PersistentList;
use semio_framework_value::retained_clone::{RetainedCloneSource,RetainedCloneSourceTake};
use protocol::mutation::retained::RetainedFieldPreparation;
/// 🧵️ The original list, current private root and displaced aliases retain independent closure.
pub(super)struct CascadeFilter<T:RetireOwned+Send+Sync+'static>{stage:Option<Box<RetainedFieldPreparation<PersistentList<T>>>>,splice:Option<Box<RowListPreparation<T>>>,source:ManuallyDrop<Option<RetainedCloneSource<PersistentList<T>>>>,next:ManuallyDrop<Option<PersistentList<T>>>,retirement:RetainedCloneClose,body:Option<usize>,rank:usize,removed:usize,weight:usize,phase:u8,closing:bool,predicate:fn(&T,u32)->usize}
impl<T:RetireOwned+Send+Sync+'static>CascadeFilter<T>{
 pub(super)fn new(predicate:fn(&T,u32)->usize)->Self{Self{stage:None,splice:None,source:ManuallyDrop::new(None),next:ManuallyDrop::new(None),retirement:Default::default(),body:None,rank:0,removed:0,weight:0,phase:0,closing:false,predicate}}
 pub(super)fn ready(&self)->bool{!self.closing&&self.phase==11}
 pub(super)fn weight(&self)->usize{self.weight}
 pub(super)fn demand(&self,original:RetainedCloneRef<'_,PersistentList<T>>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase>=11||self.body.is_some_and(|v|v!=body){return Err(invalid())}match self.phase{
 0=>nested(birth::<RetainedFieldPreparation<PersistentList<T>>>(),size_of::<usize>()),1=>nested(self.stage.as_ref().ok_or_else(invalid)?.demand(original,body.saturating_sub(1))?,1),2=>nested(self.stage.as_ref().ok_or_else(invalid)?.exchange_demand()?,size_of::<Option<PersistentList<T>>>()+1),3=>cursor_demand(&self.stage,body),4=>{let d=RetainedCloneSource::<PersistentList<T>>::owned_constructor_demand::<()>();Ok(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth+1, ..scalar(RetainedCloneSource::<PersistentList<T>>::constructor_copy_bytes()+2*size_of::<Option<PersistentList<T>>>()+2*size_of::<Option<RetainedCloneSource<PersistentList<T>>>>()+1)})},5=>Ok(scalar(size_of::<T>()+8*size_of::<usize>()+1)),6=>Ok(birth::<RowListPreparation<T>>()),7=>nested(self.splice.as_ref().ok_or_else(invalid)?.demand(self.source.as_ref().ok_or_else(invalid)?.borrow(),None)?,1),8=>nested(self.splice.as_ref().ok_or_else(invalid)?.take_demand()?,2*size_of::<Option<PersistentList<T>>>()+1),9=>cursor_demand(&self.splice,body),10=>self.source_close_demand(body),_=>Err(invalid())}}
 pub(super)fn advance(&mut self,original:RetainedCloneRef<'_,PersistentList<T>>,key:u32,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(original,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=receipt(d);self.body=Some(body);match self.phase{
 0=>{self.stage=Some(Box::default());self.phase=1},1=>{let c=self.stage.as_mut().ok_or_else(invalid)?;p=add(c.advance(original,body.saturating_sub(1),child(g,1))?.progress(),1)?;if c.value().is_some(){self.phase=2}},2=>{let c=self.stage.as_mut().ok_or_else(invalid)?;let(v,paid)=c.take(child(g,size_of::<Option<PersistentList<T>>>()+1))?;*self.next=Some(v.ok_or_else(invalid)?);p=add(paid,size_of::<Option<PersistentList<T>>>()+1)?;c.begin_close();self.phase=3},3=>{p=close_cursor(&mut self.stage,g)?;if self.stage.is_none(){self.phase=4}},4=>{let extra=2*size_of::<Option<PersistentList<T>>>()+2*size_of::<Option<RetainedCloneSource<PersistentList<T>>>>()+1;let value=self.next.take().ok_or_else(invalid)?;match RetainedCloneSource::admit_owned(value,(),child(g,extra)){Ok((s,paid))=>{*self.source=Some(s);p=add(paid,extra)?;self.phase=5},Err((e,v,()))=>{*self.next=Some(v);return Err(e)}}},5=>{let rows=self.source.as_ref().ok_or_else(invalid)?.borrow();if self.rank==rows.get().len(){self.phase=11}else{let weight=(self.predicate)(rows.get().get(self.rank).ok_or_else(invalid)?,key);if weight==0{self.rank+=1}else{self.removed+=1;self.weight=self.weight.checked_add(weight).ok_or_else(invalid)?;self.phase=6}}},6=>{self.splice=Some(Box::new(RowListPreparation::new(RowChange::Remove,self.rank)));self.phase=7},7=>{let c=self.splice.as_mut().ok_or_else(invalid)?;p=add(c.advance(self.source.as_ref().ok_or_else(invalid)?.borrow(),None,child(g,1))?.progress(),1)?;if c.output_ready(){self.phase=8}},8=>{let extra=2*size_of::<Option<PersistentList<T>>>()+1;let c=self.splice.as_mut().ok_or_else(invalid)?;let(v,paid)=c.take(child(g,extra))?.ok_or_else(invalid)?;*self.next=Some(v);c.begin_close();p=add(paid,extra)?;self.phase=9},9=>{p=close_cursor(&mut self.splice,g)?;if self.splice.is_none(){self.phase=10}},10=>{p=self.close_source(g)?;if self.source.is_none(){self.phase=4}},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original Energy cascade list")?;Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub(super)fn take_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid())}nested(self.source.as_ref().ok_or_else(invalid)?.next_take_demand(body)?,2*size_of::<Option<RetainedCloneSource<PersistentList<T>>>>()+1)}
 pub(super)fn take(&mut self,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneSourceTake<PersistentList<T>>,ValueError>{let d=self.take_demand(body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneSourceTake::Pending(Default::default()))}let extra=2*size_of::<Option<RetainedCloneSource<PersistentList<T>>>>()+1;match self.source.as_mut().ok_or_else(invalid)?.take_authority(child(g,extra))?{RetainedCloneSourceTake::Pending(p)=>Ok(RetainedCloneSourceTake::Pending(add(p,extra)?)),RetainedCloneSourceTake::Ready(v,p)=>{drop(self.source.take());self.phase=12;Ok(RetainedCloneSourceTake::Ready(v,add(p,extra)?))}}}
 fn source_close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{let s=self.source.as_ref().ok_or_else(invalid)?;if s.terminal_is_empty(){Ok(scalar(2*size_of::<Option<RetainedCloneSource<PersistentList<T>>>>()))}else{s.next_close_demand(body)}}
 fn close_source(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{let d=self.source_close_demand(self.body.unwrap_or(g.maximum_copy_bytes))?;if !retained_mutation_demand_fits(d,g){return Ok(Default::default())}let s=self.source.as_mut().ok_or_else(invalid)?;if s.terminal_is_empty(){drop(self.source.take());Ok(receipt(d))}else{s.close_step(g).map(|s|s.progress())}}
 pub(super)fn begin_close(&mut self){self.closing=true;if let Some(c)=self.stage.as_mut(){c.begin_close()}if let Some(c)=self.splice.as_mut(){c.begin_close()}}
}
impl<T:RetireOwned+Send+Sync+'static>CursorClose for CascadeFilter<T>{
 fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{let b=self.body.unwrap_or(b);if self.stage.is_some(){return cursor_demand(&self.stage,b)}if self.splice.is_some(){return cursor_demand(&self.splice,b)}if self.source.is_some(){return self.source_close_demand(b)}self.retirement.next_owner_demands::<PersistentList<T>>(self.next.is_some(),&None,b)}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let b=self.body.unwrap_or(g.maximum_copy_bytes);let d=self.close_demand(b)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()))}let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes,..g};let p=if self.stage.is_some(){close_cursor(&mut self.stage,g)?}else if self.splice.is_some(){close_cursor(&mut self.splice,g)?}else if self.source.is_some(){self.close_source(g)?}else if !self.retirement.is_empty(){self.retirement.select(b)?.step(g)?.progress()}else if let Some(s)=self.retirement.begin_granted(&mut self.next,g)?{s.progress()}else{Default::default()};Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn terminal_is_empty(&self)->bool{self.stage.is_none()&&self.splice.is_none()&&self.source.is_none()&&self.next.is_none()&&self.retirement.is_empty()}
}
impl<T:RetireOwned+Send+Sync+'static>Drop for CascadeFilter<T>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"an original cascade retains list custody");if empty{unsafe{ManuallyDrop::drop(&mut self.source);ManuallyDrop::drop(&mut self.next)}}}}
